commands.command:
set -eu
cat >/tmp/inventory-nginx.conf <<'NGINX'
upstream inventory_backends {
    server 10.100.72.11:8080 max_fails=2 fail_timeout=5s;
    server 10.100.72.12:8080 max_fails=2 fail_timeout=5s;
    keepalive 16;
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location = /lb-healthz {
        access_log off;
        default_type text/plain;
        return 200 "healthy load-balancer=node1\n";
    }

    location / {
        proxy_pass http://inventory_backends;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_next_upstream error timeout http_500 http_502 http_503 http_504;
    }
}
NGINX
sudo -n install -o root -g root -m 0644 /tmp/inventory-nginx.conf /etc/nginx/sites-available/inventory
sudo -n ln -sfn /etc/nginx/sites-available/inventory /etc/nginx/sites-enabled/inventory
sudo -n rm -f /etc/nginx/sites-enabled/default
sudo -n nginx -t
sudo -n systemctl enable nginx.service
sudo -n systemctl reload nginx.service
systemctl is-active nginx.service
systemctl is-enabled nginx.service
ss -tlnp | grep ':80 '
curl -fsS "http://10.100.72.11:8080/healthz"
curl -fsS "http://10.100.72.12:8080/healthz"
curl -fsS -D - "http://$NODE_IP/" | sed -n '1,12p'

